<script lang="ts">
  import * as ECharts from 'echarts';
  import { locale } from '$lib/i18n';
  import type { MissionInput, MissionResult } from '$core/types';
  import Chart from './Chart.svelte';
  import Icon from './Icon.svelte';
  import RotorCoverage from './RotorCoverage.svelte';

  export let result: MissionResult | null = null;
  export let input: MissionInput;
  $: en = $locale === 'en';
  const number = (value: number, digits = 1) => Number.isFinite(value) ? value.toFixed(digits) : '—';
  const labels = (name: 'hover' | 'cruise' | 'climb') => en ? ({ hover: 'Hover', cruise: 'Cruise', climb: 'Climb' }[name]) : ({ hover: 'هاور', cruise: 'کروز', climb: 'اوج‌گیری' }[name]);
  const warningLabels: Record<string, [string, string]> = {
    'battery-continuous-current': ['Battery continuous current', 'جریان دائم باتری'], 'battery-burst-current': ['Battery burst current', 'جریان لحظه‌ای باتری'], 'esc-continuous-current': ['ESC continuous current', 'جریان دائم ESC'], 'esc-burst-current': ['ESC burst current', 'جریان لحظه‌ای ESC'], 'motor-current': ['Motor current limit', 'جریان مجاز موتور'], 'motor-power': ['Motor power limit', 'توان مجاز موتور'], 'voltage-sag': ['Battery voltage sag', 'افت ولتاژ باتری'], 'insufficient-thrust': ['Insufficient thrust', 'رانش ناکافی'], 'propeller-clearance': ['Propeller clearance', 'فاصلهٔ آزاد ملخ'], 'curve-range': ['Operating point outside test curve', 'نقطهٔ کاری بیرون از منحنی تست'], 'missing-thermal-data': ['Motor thermal data missing', 'دادهٔ حرارتی موتور ناقص']
  };
  const text = (fa: string, english: string) => en ? english : fa;
  const axisStyle = { color: '#60769d', fontFamily: 'Inter, Vazir, sans-serif' };
  const baseGrid = { left: 46, right: 46, top: 34, bottom: 36 };
  $: curveOption = result ? ({ animationDuration: 600, animationEasing: 'cubicOut', grid: baseGrid, tooltip: { trigger: 'axis', confine: true }, legend: { top: 0, right: 0, textStyle: axisStyle }, xAxis: { type: 'category', data: result.points.map((p) => labels(p.name)), axisLabel: axisStyle, axisLine: { lineStyle: { color: '#a7bddc' } } }, yAxis: { type: 'value', name: 'N', nameTextStyle: axisStyle, axisLabel: axisStyle, splitLine: { lineStyle: { color: '#d7e4f5' } } }, series: [{ name: text('رانش', 'Thrust'), type: 'line', smooth: true, symbol: 'circle', symbolSize: 8, data: result.points.map((p) => p.thrustN), lineStyle: { width: 3, color: '#1167fa' }, itemStyle: { color: '#1167fa', borderColor: '#fff', borderWidth: 2 }, areaStyle: { color: 'rgba(17,103,250,.12)' } }] }) as ECharts.EChartsOption : null;
  $: currentOption = result ? ({ animationDuration: 680, animationEasing: 'cubicOut', grid: baseGrid, tooltip: { trigger: 'axis', confine: true }, legend: { top: 0, right: 0, textStyle: axisStyle }, xAxis: { type: 'category', data: result.points.map((p) => labels(p.name)), axisLabel: axisStyle, axisLine: { lineStyle: { color: '#a7bddc' } } }, yAxis: [{ type: 'value', name: 'A', axisLabel: axisStyle, splitLine: { lineStyle: { color: '#d7e4f5' } } }, { type: 'value', name: 'W', axisLabel: axisStyle, splitLine: { show: false } }], series: [{ name: text('جریان', 'Current'), type: 'line', smooth: true, data: result.points.map((p) => p.totalCurrentA), lineStyle: { width: 2.5, color: '#18b879' }, itemStyle: { color: '#18b879' } }, { name: text('توان', 'Power'), type: 'line', yAxisIndex: 1, smooth: true, data: result.points.map((p) => p.totalPowerW), lineStyle: { width: 2.5, color: '#f28b22' }, itemStyle: { color: '#f28b22' } }] }) as ECharts.EChartsOption : null;
  $: speedOption = result ? ({ animationDuration: 680, animationEasing: 'cubicOut', grid: baseGrid, tooltip: { trigger: 'axis', confine: true }, legend: { top: 0, right: 0, textStyle: axisStyle }, xAxis: { type: 'category', data: result.speedProfile.map((p) => number(p.speedMps)), name: 'm/s', nameTextStyle: axisStyle, axisLabel: axisStyle, axisLine: { lineStyle: { color: '#a7bddc' } } }, yAxis: [{ type: 'value', name: 'min', axisLabel: axisStyle, splitLine: { lineStyle: { color: '#d7e4f5' } } }, { type: 'value', name: 'km', axisLabel: axisStyle, splitLine: { show: false } }], series: [{ name: text('زمان پرواز', 'Flight time'), type: 'line', smooth: true, data: result.speedProfile.map((p) => p.flightTimeMin), lineStyle: { width: 2.5, color: '#1167fa' }, itemStyle: { color: '#1167fa' } }, { name: text('برد', 'Range'), type: 'line', yAxisIndex: 1, smooth: true, data: result.speedProfile.map((p) => p.rangeKm), lineStyle: { width: 2.5, color: '#8d63e8' }, itemStyle: { color: '#8d63e8' } }] }) as ECharts.EChartsOption : null;
  $: altitudeOption = result ? ({ animationDuration: 700, animationEasing: 'cubicOut', grid: baseGrid, tooltip: { trigger: 'axis', confine: true }, legend: { top: 0, right: 0, textStyle: axisStyle }, xAxis: { type: 'category', data: result.altitudeProfile.map((p) => Math.round(p.altitudeM)), name: 'm', nameTextStyle: axisStyle, axisLabel: axisStyle, axisLine: { lineStyle: { color: '#a7bddc' } } }, yAxis: [{ type: 'value', name: 'N', axisLabel: axisStyle, splitLine: { lineStyle: { color: '#d7e4f5' } } }, { type: 'value', name: '%', axisLabel: axisStyle, splitLine: { show: false } }], series: [{ name: text('رانش موجود', 'Available thrust'), type: 'line', smooth: true, data: result.altitudeProfile.map((p) => p.availableThrustN), lineStyle: { width: 2.5, color: '#18b879' }, itemStyle: { color: '#18b879' } }, { name: text('حاشیهٔ رانش', 'Thrust margin'), type: 'line', yAxisIndex: 1, smooth: true, data: result.altitudeProfile.map((p) => p.thrustMargin * 100), lineStyle: { width: 2.5, color: '#f28b22' }, itemStyle: { color: '#f28b22' } }] }) as ECharts.EChartsOption : null;
  $: powerOption = result ? ({ animationDuration: 620, animationEasing: 'cubicOut', tooltip: { trigger: 'item', formatter: (item: any) => `${item.name}: ${number(Number(item.value), 0)} W` }, legend: { bottom: 0, left: 'center', textStyle: axisStyle }, series: [{ type: 'pie', radius: ['45%', '70%'], center: ['50%', '43%'], itemStyle: { borderColor: '#fff', borderWidth: 3 }, label: { show: true, formatter: '{d}%', color: '#141c56', fontFamily: 'Inter, Vazir, sans-serif', fontWeight: 700 }, data: [{ value: result.power.propulsiveW, name: text('پروانه', 'Propeller'), itemStyle: { color: '#1167fa' } }, { value: result.power.motorLossW, name: text('تلفات موتور', 'Motor loss'), itemStyle: { color: '#f28b22' } }, { value: result.power.escLossW, name: 'ESC loss', itemStyle: { color: '#18b879' } }, { value: result.power.batteryLossW, name: text('تلفات باتری', 'Battery loss'), itemStyle: { color: '#8d63e8' } }] }] }) as ECharts.EChartsOption : null;
</script>

{#if result}
