    <div class="metrics">
      <article><span class="metric__icon metric__icon--green"><Icon name="clock" size={22} /></span><div><small>{text('زمان قابل استفاده', 'Usable flight time')}</small><strong class="data">{number(result.flightTimeMin)} <em>min</em></strong></div></article>
      <article><span class="metric__icon metric__icon--blue"><Icon name="pin" size={22} /></span><div><small>{text('برد برآوردی', 'Estimated range')}</small><strong class="data">{number(result.rangeKm)} <em>km</em></strong></div></article>
      <article><span class="metric__icon metric__icon--orange"><Icon name="rocket" size={22} /></span><div><small>{text('نسبت رانش به وزن', 'Thrust-to-weight')}</small><strong class="data">{number(result.thrustToWeight)} <em>: 1</em></strong></div></article>
      <article><span class="metric__icon metric__icon--yellow"><Icon name="bolt" size={22} /></span><div><small>{text('توان هاور', 'Hover power')}</small><strong class="data">{number(result.totalPowerW, 0)} <em>W</em></strong></div></article>
      <article><span class="metric__icon metric__icon--purple"><Icon name="ceiling" size={22} /></span><div><small>{text('سقف پیشنهادی', 'Suggested ceiling')}</small><strong class="data">{result.ceilingM == null ? '—' : number(result.ceilingM, 0)} <em>{result.ceilingM == null ? '' : 'm'}</em></strong></div></article>
      <article><span class="metric__icon metric__icon--cyan"><Icon name="bolt" size={22} /></span><div><small>{text('ولتاژ زیر بار', 'Loaded voltage')}</small><strong class="data">{number(result.loadedVoltageV, 1)} <em>V</em></strong></div></article>
    </div>
    <div class="fact-strip"><span>{text('جرم برخاست', 'Takeoff mass')} <b class="data">{number(result.takeoffMassKg, 2)} kg</b></span><span>{text('چگالی هوا', 'Air density')} <b class="data">{number(result.airDensityKgM3, 3)} kg/m³</b></span><span>{text('رانش ویژه', 'Specific thrust')} <b class="data">{number(result.specificThrustGPerW, 2)} g/W</b></span><span>{text('دمای موتور', 'Motor temperature')} <b class="data">{result.motorTemperatureC == null ? '—' : `${number(result.motorTemperatureC, 0)} °C`}</b></span></div>
