      <article><div class="chart-head"><h3>{text('جریان و توان', 'Current and power')}</h3><span class="data">A · W</span></div>{#if currentOption}<Chart option={currentOption} ariaLabel={text('نمودار جریان و توان', 'Current and power chart')} />{/if}</article>
      <article><div class="chart-head"><h3>{text('زمان و برد نسبت به سرعت', 'Time and range by speed')}</h3><span class="data">min · km</span></div>{#if speedOption}<Chart option={speedOption} ariaLabel={text('نمودار زمان و برد نسبت به سرعت', 'Speed versus time and range chart')} />{/if}</article>
      <article><div class="chart-head"><h3>{text('رانش و حاشیه نسبت به ارتفاع', 'Thrust and margin by altitude')}</h3><span class="data">N · %</span></div>{#if altitudeOption}<Chart option={altitudeOption} ariaLabel={text('نمودار رانش و حاشیه نسبت به ارتفاع', 'Altitude thrust and margin chart')} />{/if}</article>
      <article class="chart-grid__power"><div class="chart-head"><h3>{text('توزیع توان و تلفات', 'Power and loss breakdown')}</h3><span class="data">{number(result.totalPowerW, 0)} W</span></div>{#if powerOption}<Chart option={powerOption} ariaLabel={text('نمودار توزیع توان', 'Power breakdown chart')} />{/if}</article>
    </div>
    <article class="coverage"><div class="chart-head"><h3>{text('پوشش و فاصلهٔ روتورها', 'Rotor layout and clearance')}</h3><span class="data">{number(result.thrustMargin * 100, 0)}%</span></div><RotorCoverage rotorCount={input.airframe.rotorCount} frameSizeM={input.airframe.frameSizeM} propellerDiameterM={input.propeller.diameterM} layout={input.airframe.layout} /></article>
    <article class="warnings"><div class="chart-head"><h3>{text('هشدارها', 'Checks')}</h3><span class="data">{result.warnings.length}</span></div>{#if result.warnings.length === 0}<p>{text('موردی برای بررسی نیست.', 'No checks need attention.')}</p>{:else}<ul>{#each result.warnings as warning}<li class:critical={warning.severity === 'critical'}><b>{warning.severity === 'critical' ? '!' : '·'}</b><span>{warningLabels[warning.code]?.[en ? 0 : 1] ?? text('نیازمند بررسی', 'Review required')}</span></li>{/each}</ul>{/if}</article>
  </section>
{/if}

<style>
