  .chart-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px; }.chart-grid>article,.coverage,.warnings { min-width:0; border:1px solid var(--line); border-radius:var(--radius); background:var(--surface); padding:15px; box-shadow:var(--shadow-soft); }.chart-grid__power { grid-column:1/-1; }.chart-head h3 { margin:0; font-size:14px; }.chart-head>span { color:var(--muted); font-size:12px; }.warnings p { margin:10px 0 0; color:var(--muted); font-size:13px; }.warnings ul { display:grid; gap:8px; margin:12px 0 0; padding:0; list-style:none; color:var(--orange); font-size:13px; }.warnings li { display:flex; gap:8px; align-items:center; }.warnings li.critical { color:var(--danger); }.warnings li b { display:grid; width:20px; height:20px; place-items:center; border-radius:50%; background:currentColor; color:var(--surface); font-size:12px; }.coverage :global(.coverage) { margin-top:12px; }
  @media (max-width:900px) { .metrics { grid-template-columns:repeat(2,minmax(0,1fr)); } } @media (max-width:720px) { .chart-grid { grid-template-columns:minmax(0,1fr); }.chart-grid__power { grid-column:auto; }.fact-strip { gap:8px 12px; }.metrics article { padding:11px; } } @media (max-width:420px) { .metrics { grid-template-columns:minmax(0,1fr); }.result-heading h2 { font-size:23px; }.state { font-size:11px; padding:4px 8px; } }
</style>
